// Generated by scripts/generate-workflow-blueprints.ts (extra questions); edit the specs there and re-run rather than editing by hand.
import { o, s, type QuestionSet } from "@/lib/interview-questions";

const bank: QuestionSet = {
  subjective: [
    s(5, "Walk me through the end-to-end architecture of this Langflow flow.", "A client posts a structured brief to POST /api/v1/run/<flow-id>, with optional tweaks for the model, temperature or channel list. The first Prompt and model pair turns product, audience and features plus brand voice into a benefit list. A second chain turns those benefits into a fixed number of headline variants, each tagged with its source benefit. A third chain runs once per channel with that channel's spec and returns JSON. A custom Python component then checks every line against brand rules. Lines that pass are kept. Flagged lines go to a rewrite prompt and back through the same check, up to a retry cap. Copy that still fails goes to human review. Approved copy returns grouped by channel and variant, and Langfuse or LangSmith traces every step."),
    s(4, "Why is free text allowed only in a notes field of the brief?", "Each chain is a Prompt component with named variables such as {product}, {audience} and {features}. If those values arrive as clean, typed fields, I know exactly what lands in each slot, and I can validate the brief before spending a model call. Free text everywhere would make the prompts unpredictable. A marketer could paste a claim into the features field and it would flow straight into the benefits. Keeping free text in one notes field means only one place needs careful handling. I can label it in the prompt as background context, not as instructions or approved claims. It also gives tests and traces a stable input shape, so regressions are easier to spot."),
    s(4, "How would you design the data model for the brief and the output?", "The brief is a JSON object with product name, audience, a list of features, a price point, a list of approved claims with IDs, a list of target channels, and a notes string. The output is grouped by channel and then by headline variant. Each line carries its text, the benefit ID it uses, the claim IDs it relies on, its character count and a status of approved or needs review. Rejected lines also carry their violation list. I would add a run ID, the brand-rule version and the prompt versions to every output. Then any line can be traced back to its inputs and to the exact rules it was checked against."),
    s(4, "Why tag each headline variant with the benefit it uses?", "The tag creates a traceable chain from feature to benefit to headline to ad line. The brand check can then confirm that a headline only relies on benefits derived from supplied features and approved claims. When a reviewer sees a risky line, they can see which benefit it came from and whether the problem started in the benefits chain or the headline chain. Later steps can also use the tag to group or filter copy, for example to show a marketer every variant built on a price benefit. Without the tag, you only have free-floating sentences and no audit trail for claims."),
    s(5, "Why should the ad copy chain return structured JSON instead of prose?", "The brand-rule component needs to check each line separately: headline, body and call to action, each with its own channel limit. If the model returns prose, I would have to guess where one field ends and the next begins, which is fragile. With JSON keyed by channel, variant and field, the checker can measure length per field, report violations against an exact line, and send only that line to rewrite. The final response to the marketer is also JSON grouped by channel and variant, so no conversion step is needed. The one cost is parse failures, which I treat as a failed check and retry, not as copy to ship."),
    s(5, "How do you stop the model from inventing product claims?", "I use several layers. In the benefits prompt, I tell the model to derive benefits only from the supplied features and to cite which feature each benefit uses. Headlines must carry a benefit tag, so claims stay traceable. The real enforcement is the deterministic check, though. It compares claim-like statements against the approved claims list and flags anything not on it, such as superlatives, numbers or guarantees that were not supplied. A flagged line is rewritten with the reason attached, then checked again. If it still fails, a human sees it. I never rely on the prompt alone, because instructions reduce invented claims but do not guarantee their absence."),
    s(4, "How does the rewrite loop avoid running forever or burning cost?", "The loop has a hard retry cap, set as a counter in the flow state that the custom component checks before routing another rewrite. Each pass sends only the flagged lines, not the whole draft, so the token cost shrinks as lines pass. When the cap is hit, the remaining failing lines go to the human review queue with their violations, and approved lines can still return. I also track retries per run in tracing. If a rule keeps causing retries, the prompt or the rule probably needs fixing. More attempts will not solve that."),
    s(4, "Why rewrite only the flagged lines rather than regenerating the whole set?", "Regenerating everything throws away lines that already passed, and the new versions might fail in new ways, so the loop may never settle. Rewriting only flagged lines keeps the good copy stable, uses fewer tokens, and gives the model a narrow, clear task: fix this line for this reason within this limit. It also makes reviews easier, because a marketer sees which lines changed and why. The rewritten line still goes through the full check, not a partial one. That way a fix for length cannot slip in a banned word or an unapproved claim."),
    s(3, "What should a violation record from the brand-check component contain?", "Each record should hold the exact offending line text and its location: channel, variant and field. It should also hold the rule type, such as length, banned word, missing disclaimer or unapproved claim, and a specific reason. For example, the line is 142 characters against a 125 limit, or the word 'guaranteed' is banned. Adding the measured value and the allowed value helps the rewrite prompt fix the line precisely. I also include the rule ID and the rule-set version. The same record goes to the rewrite prompt, the human review queue and the trace, so everyone sees the same reason."),
    s(4, "How would you estimate the number of model calls per run?", "With C channels, the baseline is one benefits call, one headline call and C ad copy calls, which is 2 + C. If the rewrite step batches all flagged lines into one call per round, the worst case adds up to R calls, where R is the retry cap. So the total is at most 2 + C + R. If rewrites run per line, the worst case grows with the number of flagged lines times R. As an illustration, three channels and a cap of two gives five calls in the normal case and seven at worst with batching. I would confirm real token sizes and latency from traces rather than guessing."),
    s(3, "How would you scale this flow to many concurrent campaigns?", "Each run is mostly stateless: a brief goes in and grouped JSON comes out. That means I can run several Langflow instances behind a load balancer and scale them horizontally. The main limit is usually the model provider's rate limits, so I would put a queue in front for bulk jobs and control concurrency per provider key. Per-channel ad calls are independent, so they can run in parallel to cut latency. Brand rules should be loaded from a versioned store and cached, not fetched on every line. For very large batches, I would use async submission, through a webhook or a job queue, rather than holding HTTP connections open."),
    s(4, "How do you handle prompt injection through the notes field?", "The notes field is the only free text, so I treat it as untrusted data. In the prompt, I place it in a clearly labelled block and instruct the model that it is background and cannot add claims or change rules. I can also set a length limit on notes and strip obvious instruction patterns before the run. The important defence is structural, though. Whatever the notes cause the model to write, the deterministic check still rejects unapproved claims, banned words and over-length lines. Injection can waste a retry, but it cannot push non-compliant copy past the gate."),
    s(4, "How would you secure the run endpoint?", "I would not expose the Langflow instance directly to marketers' browsers. A backend service authenticates the user, validates the brief against the schema, and then calls the flow with a server-side Langflow API key that is never shipped to clients. The Langflow instance sits on a private network or behind a gateway with TLS and rate limiting. Model provider keys are stored as secrets in Langflow, not written into flows or exports. I would also log who submitted each brief and link that to the run trace, so any approved copy has an accountable requester."),
    s(4, "Tweaks are powerful. How do you stop a caller from misusing them?", "Tweaks can override any component setting, including prompt text or the brand-rule inputs, which could weaken the gate. So the calling service should build tweaks itself from an allow-list: the model choice within approved options, temperature within a range, and the channel list from known channel specs. Callers should never pass raw tweak payloads through. The brand-rule component should load rules from a trusted versioned source rather than from a tweakable text field. I would log the tweaks used in each run so traces show exactly what configuration produced a piece of copy."),
    s(4, "What happens when the model returns invalid or incomplete JSON?", "I parse the output in the custom component or in a parsing step before the brand check. If parsing fails, or required fields such as headline, body or call to action are missing, I treat it as a violation for that channel and send it back with a clear reason, such as invalid JSON or a missing field. This uses the same retry cap as other failures. If it still cannot parse after the cap, that channel goes to human review while other channels can still return. I never try to rescue copy by loosely scraping text from broken output, because that is how unchecked lines slip through."),
    s(4, "How would you test this flow before rolling it out?", "First, I iterate on prompts in the Langflow Playground with real sample briefs. Then I write unit tests for the custom brand-check component in plain Python, with cases for each rule: over-length lines, banned words, missing disclaimers and unapproved claims, including edge cases like Devanagari text and emoji. Next comes a regression set of golden briefs run through the API. For these I assert structure, zero shipped violations and acceptable first-pass rates, not exact wording. I also add adversarial briefs with injection attempts in notes. Every prompt or rule change runs this suite before deployment."),
    s(4, "A marketer says a headline sounds off-brand. How do you use tracing to debug it?", "I find the run by its run ID in Langfuse or LangSmith. The trace shows each chain's inputs, outputs and latency. I check the headline step's input benefit list. If the benefit was already off, the problem started in the benefits chain, perhaps from vague features or a weak brand voice text. If the benefits look fine, I look at the headline prompt and temperature, including any tweaks. Then I check whether the brand check should have caught it. If tone is the issue, that is a gap in the rules, because deterministic checks will not catch subtle voice problems. I add the case to the regression set."),
    s(3, "How do you version prompts and brand rules?", "I export flows as JSON and keep them in source control, so prompt changes go through review like code. Brand rules, such as banned words, disclaimers and channel limits, live in a separate versioned store or file that the custom component loads, rather than being hardcoded. Each run records the flow version and rule-set version in its output and trace. Then I can answer questions like which rules approved this line last month. When rules change, I rerun the golden briefs to check for regressions before promoting the new version."),
    s(3, "How would you design the human review queue?", "Each queue item holds the original brief, the run ID, the failing lines with their violation records, the attempted rewrites and the approved lines from the same run. That gives the reviewer full context without opening traces. Reviewers can edit a line, approve it or reject it. Any edited line should pass through the same brand-check code before final approval, so humans do not accidentally ship an over-length line. Decisions are logged with the reviewer's identity. Reviewed cases also feed back into the test set and into rule or prompt fixes when the same violation keeps appearing."),
    s(3, "How do you count characters correctly for channel limits, especially with Hindi or emoji?", "Character counts are not universal. Python's len counts code points, a single Devanagari syllable can be several code points, and some emoji are multiple code points joined together. A platform may count user-visible characters or use its own rule. So the checker should use the same counting method the target channel uses, defined in the channel spec, and test it with real Hindi and emoji samples. If a channel's method is unclear, I count conservatively, so I never approve something the platform might cut off. Length should be checked only in this code, never trusted from the model."),
    s(3, "Where could an LLM-based check still add value alongside the deterministic one?", "Deterministic code handles hard rules well: lengths, banned words, required disclaimers and exact claim matching. It is weaker on fuzzy issues, such as whether a line implies an unapproved claim through paraphrase, or whether the tone fits the brand voice. An LLM judge can flag those as advisory signals. I would make it able only to add flags, never to remove a deterministic violation. Its flags could send a line to rewrite or review, so it only tightens the gate. I would monitor its false positives, because an over-eager judge inflates retries and review load."),
    s(4, "Why not use an Agent component that decides the steps itself instead of fixed chains?", "The order here is known and fixed: benefits, headlines, per-channel copy, check, rewrite. An agent adds a planning step that can skip, reorder or repeat things in ways that are hard to test and audit, and it usually costs more calls. Fixed chains give predictable cost, stable traces and clear points to attach the compliance gate. An agent might make sense around the edges, for example a helper that answers questions using tools. But the path that produces shippable copy should be deterministic in structure, with the brand check impossible to skip."),
    s(2, "How could other teams' tools use this flow through MCP?", "Langflow can act as an MCP server and expose flows as tools to MCP clients. Another team's assistant could then call the copy flow as a tool, passing a structured brief and getting grouped JSON back. The tool should accept the same validated brief schema, not free-form requests, and it should go through the same authentication and tweak allow-list as the API. Because the brand check sits inside the flow, every MCP caller gets the same gate. I would describe the tool clearly so clients know it returns approved copy plus items pending human review."),
    s(3, "The same brief gives different copy on each run. Is that a consistency problem?", "Variety in wording is often fine for marketing, but compliance must be consistent. Every run, whatever it generates, passes the same deterministic check against the same rule version. If marketers need repeatable output, I lower the temperature for that campaign through a tweak and store the approved output, so we serve the stored copy rather than regenerating it. The reproducible record is the trace plus the saved JSON with flow and rule versions. Regeneration is not a reliable way to get the same text back."),
    s(4, "What happens if the model provider times out halfway through a run?", "Calls to the model should have timeouts and a small number of retries with backoff for transient errors. If a single channel's call keeps failing, I return the channels that completed and mark that channel as failed, rather than failing the whole run. If the benefits or headline step fails, nothing downstream can run, so the whole run fails with a clear error and the client can resubmit. For bulk jobs, I would run asynchronously with a job ID so retries are safe. Unfinished or unchecked copy is never returned as approved."),
    s(2, "How would you extend the flow to produce Hindi or other regional-language ads?", "I would add a language field to the brief or the channel spec and pass it into the prompts as a variable. The brand rules then need per-language versions: banned words and required disclaimers in Hindi, and approved claims with reviewed translations. Otherwise the claim check will miss paraphrased claims. Length counting must handle Devanagari correctly. I would also add native-speaker review samples to the test set, and route new languages through human review more heavily until their first-pass rates are trusted."),
    s(3, "What metrics would you track to know the flow is working well?", "I would track the first-pass approval rate, the average number of rewrite rounds, the rate of runs hitting the retry cap, and the human review queue rate. I would also break violations down by rule type and channel. Rising length violations on one channel suggest a prompt or spec problem. Rising unapproved-claim flags may mean the brief quality has dropped. From traces, I would watch latency and token use per chain. The key safety metric is shipped violations, which should be zero. Any escape becomes a new test case and a rule fix."),
    s(3, "Briefs may contain unreleased product details. How do you protect them in traces and logs?", "Traces capture full prompts and outputs, so they contain confidential launch information. I would self-host the tracing backend where possible, or confirm the hosted provider's data handling meets company policy. I would restrict trace access to the people who need it and set retention limits. Marketer identity and any personal data should not go into prompts at all. Only the brief fields the chains need should be sent to the model provider, and provider terms on data use should be checked. Exported flows and queue items need the same access controls."),
    s(3, "How would you handle a brief that has no approved claims, or claims that contradict the features?", "I validate the brief before any model call. Required fields must be present, and the channel list must match known specs. If approved claims are empty, the flow can still run, but the claim check will reject any claim-like statement. The marketer should be warned that the copy will stay feature-descriptive. If a claim contradicts the features, for example a 'fastest' claim with no supporting feature, I reject the brief or flag it for the marketer to fix. Code cannot reliably judge truth, and the flow should not silently choose one side."),
    s(2, "Does this flow need message history or session memory?", "Mostly no. Each run is a single transaction from brief to copy, and all context comes from the brief and earlier chain outputs, which are passed explicitly as variables. Adding chat memory would let earlier sessions leak into new campaigns and make output harder to reproduce. Memory per session ID becomes useful only if I add an interactive refinement mode, where a marketer says 'make variant two punchier'. Even then, every refined line must go back through the same brand check before it is returned."),
  ],
  objective: [
    o(5, "Which endpoint pattern does a client use to run a Langflow flow over the API?", ["POST /api/v1/run/<flow-id>","GET /api/v1/flows/<flow-id>/execute","POST /api/v2/chat/<flow-id>","PUT /api/v1/run/<flow-id>"], 0, "Langflow runs a flow with POST /api/v1/run/<flow-id>, passing input and optional tweaks."),
    o(5, "What are tweaks used for in a Langflow API call?", ["Permanently editing the saved flow","Overriding component settings for that run only","Adding new components at runtime","Changing the API key for the request"], 1, "Tweaks override settings such as model or temperature for a single run without modifying the saved flow."),
    o(4, "In the benefits chain, how does the brief reach the Prompt component?", ["As a single pasted paragraph","Through named variables such as {product}, {audience} and {features}","Through the model's system settings only","Through a vector store lookup"], 1, "The Prompt component is filled with named variables, which keeps inputs predictable."),
    o(4, "Why is free text limited to the notes field in the brief?", ["Langflow cannot accept free text","It makes the model run faster","It keeps prompt variables predictable and limits where untrusted text enters","It removes the need for brand checks"], 2, "Structured fields keep each variable's content known, and untrusted text is confined to one field."),
    o(4, "What is the main purpose of tagging each headline with its benefit?", ["Improving SEO ranking","Tracing claims back to supplied inputs for checks and review","Reducing token usage","Selecting the model per headline"], 1, "Benefit tags let later steps and reviewers trace each claim back to the inputs."),
    o(5, "Why does the ad copy chain return structured JSON?", ["So each field can be checked and rewritten individually","Because models cannot produce prose","To avoid using Prompt components","JSON outputs are cheaper to generate"], 0, "Field-level structure lets the checker measure limits per line and flag exact offending lines."),
    o(4, "How does the ad copy chain get each channel's limits, tone and call to action?", ["The model is expected to know them","They are injected as variables from the channel spec on each per-channel run","They are applied only after human review","They are hardcoded in the headline chain"], 1, "The chain runs once per channel with that channel's spec injected as variables."),
    o(5, "Which component performs the brand-rule check?", ["An Agent component with web search","A vector store component","A custom Python component","The Playground"], 2, "A custom Python component deterministically checks every line and returns violations."),
    o(4, "What does the brand-check component return when lines fail?", ["A single pass or fail boolean","A list of violations including the exact offending line","A rewritten version of the copy","A confidence score only"], 1, "It returns violation records with the exact offending line, so targeted rewrites are possible."),
    o(4, "What happens to lines that fail the check on the first pass?", ["The whole draft is regenerated from scratch","Only the flagged lines go to a rewrite prompt with reasons, then are rechecked","They are shipped with a warning","They are silently dropped"], 1, "Only flagged lines are rewritten with their violation reasons and then pass through the same check again."),
    o(5, "What prevents the rewrite loop from running indefinitely?", ["A hard cap on retries","The model's context window","Langflow automatically stops after one loop","A temperature of zero"], 0, "The design uses a hard retry cap, after which failing drafts go to human review."),
    o(4, "After the retry cap is reached, where do still-failing drafts go?", ["Back to the benefits chain","Directly to the marketer as approved","To a human review queue with violations attached","To a vector store for later reuse"], 2, "Drafts that still fail go to human review, never to shipping."),
    o(4, "How is approved copy returned to the marketer?", ["As a PDF","As JSON grouped by channel and headline variant","As a single concatenated string","As a chat message in the Playground"], 1, "The output is JSON grouped by channel and headline variant."),
    o(3, "Which tracing integrations do the notes name for inspecting each chain's inputs, outputs and latency?", ["Prometheus and Grafana","LangSmith and Langfuse","Sentry and Datadog","OpenTelemetry only"], 1, "The notes list LangSmith and Langfuse as tracing integrations."),
    o(3, "With C channels, a retry cap R and one batched rewrite call per round, what is the maximum number of model calls?", ["C","2 + C","2 + C + R","C × R"], 2, "There is one benefits call, one headline call, C ad calls and at most R batched rewrite rounds."),
    o(3, "Why should a rewritten line go through the full brand check, not just the rule it failed?", ["A fix for one rule can introduce a different violation","The full check is faster","Partial checks are not supported in Python","It reduces token cost"], 0, "Shortening a line could add a banned word or unapproved claim, so every rule must be checked again."),
    o(4, "What is the safest way to handle tweaks sent by external callers?", ["Pass any tweak through unchanged","Have a backend build tweaks from an allow-list of safe settings","Disable the API entirely","Let callers edit the brand-rule text through tweaks"], 1, "Allow-listed tweaks stop callers from weakening prompts or the compliance gate."),
    o(4, "What is the strongest defence against prompt injection through the notes field?", ["A polite instruction asking the model to ignore injections","A higher temperature","The deterministic brand check that gates all output regardless of the model's text","Removing the headline chain"], 2, "Even if injection changes the model's output, code-based checks still block non-compliant copy."),
    o(3, "How should the flow treat ad copy output that fails to parse as JSON?", ["Scrape whatever text looks like copy and ship it","Treat it as a violation and retry within the cap","Ignore that channel silently","Raise the temperature and continue"], 1, "A parse failure is a failed check. It is retried within the cap and goes to review if it persists."),
    o(3, "Why can Python's len() be misleading for a Hindi ad's character limit?", ["Python cannot store Devanagari","One visible Devanagari character can be several code points, and the platform may count differently","len() counts words, not characters","len() always returns bytes"], 1, "Code points differ from user-visible characters, so counting must match the channel's rule."),
    o(3, "How do Langflow custom components work?", ["They are YAML configuration files","They are Python classes with defined inputs and outputs","They are JavaScript plugins only","They are prompts saved in a vector store"], 1, "Custom components are Python classes that declare inputs and outputs."),
    o(2, "How can a component be made available to the Agent component as a tool?", ["By switching the component to tool mode","By renaming it with a tool_ prefix","By placing it in a vector store","Components cannot be tools"], 0, "The Agent takes tools such as components in tool mode, other flows and MCP tools."),
    o(3, "What role can Langflow play with respect to MCP?", ["Only an MCP client","Only an MCP server","Both an MCP server exposing flows as tools and an MCP client","Neither"], 2, "Langflow can expose flows as tools to MCP clients and can also consume MCP tools."),
    o(3, "Why use fixed prompt chains rather than an Agent to orchestrate this workflow?", ["Agents cannot call models","The steps are known, so fixed chains give predictable cost, auditability and a gate that cannot be skipped","Fixed chains always produce better wording","Agents are not available in Langflow"], 1, "A fixed sequence keeps the compliance gate mandatory and makes runs testable and traceable."),
    o(2, "In Langflow, what does message history provide?", ["Chat memory per session id","A cache of model weights","Versioned flow exports","Rate limiting per user"], 0, "Message history stores chat memory keyed by session id, which this one-shot flow mostly does not need."),
    o(3, "Where should prompt iteration with sample briefs happen before API rollout?", ["In the Langflow Playground","Directly in production","Only in the tracing tool","In the human review queue"], 0, "The Playground is Langflow's built-in place to test flows interactively."),
    o(3, "What should be recorded with every output to support audits?", ["Only the final text","The run ID plus flow and brand-rule versions","The marketer's password","The model's raw token probabilities"], 1, "Version and run identifiers make it possible to tell which rules and prompts approved a line."),
    o(2, "For large batch submissions, which approach avoids long-held HTTP connections?", ["Raising the client timeout to hours","Asynchronous submission through webhooks or a job queue","Running all briefs in one giant prompt","Disabling tracing"], 1, "Async triggers such as webhooks or queued jobs decouple submission from completion."),
    o(4, "Which change should NOT be allowed to lower the compliance bar?", ["A tweak changing temperature within a safe range","A tweak selecting an approved model","An LLM judge clearing a line that the deterministic check flagged","Adding a new channel spec with its limits"], 2, "Advisory LLM checks may add flags but must never override deterministic violations."),
    o(3, "If one channel's model call keeps timing out, what is a reasonable behaviour?", ["Fail every channel in the run","Return completed channels and mark that channel failed, never as approved","Ship that channel's last partial output","Skip the brand check for that channel"], 1, "Partial success is fine as long as unfinished or unchecked copy is never marked approved."),
  ],
};
export default bank;
